"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[555],{597:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-02-erm-least-squares</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-2-эмпирический-риск-и-метод-наименьших-квадратов">Лабораторная\nработа 2. Эмпирический риск и метод наименьших квадратов</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 1</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 1: функция потерь (опр. 1.9), эмпирический и истинный риск\n(опр. 1.10–1.11), утв. 1.12 о несмещённости, принцип ERM (опр. 1.13),\nнормальные уравнения МНК (теорема 1.20), примеры 1.5 и 1.21</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно + домашняя работа (3–4 ч)</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Увидеть, что утверждения лекции 1 — не формальность: эмпирический\nриск действительно несмещённо оценивает истинный, но\n<strong>только</strong> для алгоритма, выбранного независимо от выборки.\nРазобрать, как выбор функции потерь определяет, что именно мы\nвосстанавливаем, и воспроизвести численный пример МНК из конспекта.</p>\n<h2 id="как-устроено-занятие">Как устроено занятие</h2>\n<p>Ноутбук разбирается в аудитории: код запускается и обсуждается по\nходу. Большая часть ячеек уже написана — их нужно <strong>прочитать и\nзапустить</strong>, разобравшись, что происходит и почему.</p>\n<p>Ячейки, помеченные <code># ✍ ЗАДАНИЕ НА СЕМИНАРЕ</code>, заполняются\nсамостоятельно прямо на занятии; их немного, и каждая занимает несколько\nстрок. Ячейки <strong>Вывод</strong> — тоже ваши: короткий ответ своими\nсловами на поставленный вопрос.</p>\n<p>Дома выполняется отдельный ноутбук <code>lab02_homework.ipynb</code>\n— там задания крупнее и делать их нужно самому.</p>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже) — и на семинаре, и в домашней\nработе.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> optimize</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LinearRegression</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell markdown">\n<hr />\n<h1 id="часть-1-функция-потерь-задаёт-что-мы-восстанавливаем">Часть 1.\nФункция потерь задаёт, что мы восстанавливаем</h1>\n<p>Определение 1.9: потеря\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mo>≥</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\mathcal L(a,x,y)\\ge0</annotation></semantics></math>\nизмеряет ошибку на одном объекте; в регрессии она зависит только от\nневязки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>=</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>y</mi></mrow><annotation encoding="application/x-tex">r = a(x) - y</annotation></semantics></math>.\nЭмпирический риск (опр. 1.10) — её среднее по выборке:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\nQ(a, X^\\ell) = \\frac1\\ell\\sum_{i=1}^{\\ell}\\mathcal L(a, x_i, y_i).\n</annotation></semantics></math></p>\n<p>Возьмём три потери и посмотрим на них как на функции невязки.</p>\n</div>\n<div id="cell005" class="cell markdown">\n<blockquote>\n<p><strong>Напоминание — квантильная потеря и потеря Хьюбера.</strong>\n<strong>Квантильная</strong> потеря штрафует перепрогноз и недопрогноз\n<em>разными</em> весами:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>r</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><mi>q</mi><mo stretchy="false" form="postfix">)</mo><mspace width="0.167em"></mspace><mi>r</mi></mrow><annotation encoding="application/x-tex">\\mathcal L(r) = (1-q)\\,r</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>≥</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">r\\ge0</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>−</mi><mi>q</mi><mspace width="0.167em"></mspace><mi>r</mi></mrow><annotation encoding="application/x-tex">-q\\,r</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>&lt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">r&lt;0</annotation></semantics></math>.\nПри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi><mo>=</mo><mn>0.5</mn></mrow><annotation encoding="application/x-tex">q = 0.5</annotation></semantics></math>\nэто половина абсолютной потери, при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi><mo>=</mo><mn>0.9</mn></mrow><annotation encoding="application/x-tex">q = 0.9</annotation></semantics></math>\nнедопрогноз в девять раз дороже перепрогноза. Нужна там, где ошибки\nнесимметричны по цене: занизить запас товара на складе хуже, чем\nзавысить.</p>\n<p><strong>Хьюбера</strong> — компромисс между квадратичной и\nабсолютной: квадратичная при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mi>r</mi><mo stretchy="false" form="prefix">|</mo><mo>≤</mo><mi>δ</mi></mrow><annotation encoding="application/x-tex">|r|\\le\\delta</annotation></semantics></math>\nи линейная дальше. Гладкая в нуле (в отличие от абсолютной, которую\nнеудобно минимизировать градиентными методами) и не даёт выбросам\nраздувать функционал квадратично.</p>\n</blockquote>\n</div>\n<div id="cell006" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loss_squared(r):</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> r <span class="op">**</span> <span class="dv">2</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loss_absolute(r):</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> np.<span class="bu">abs</span>(r)</span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loss_quantile(r, q<span class="op">=</span><span class="fl">0.75</span>):</span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Перепрогноз (r &gt; 0) штрафуется весом 1 - q, недопрогноз -- весом q.&quot;&quot;&quot;</span></span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> np.where(r <span class="op">&gt;=</span> <span class="dv">0</span>, (<span class="fl">1.0</span> <span class="op">-</span> q) <span class="op">*</span> r, <span class="op">-</span>q <span class="op">*</span> r)</span></code></pre></div>\n</div>\n<div id="cell007" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>r <span class="op">=</span> np.linspace(<span class="op">-</span><span class="dv">3</span>, <span class="dv">3</span>, <span class="dv">400</span>)</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> loss, name <span class="kw">in</span> [(loss_squared, <span class="st">&quot;квадратичная&quot;</span>), (loss_absolute, <span class="st">&quot;абсолютная&quot;</span>),</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>                   (loss_quantile, <span class="st">&quot;квантильная, q=0.75&quot;</span>)]:</span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a>    ax.plot(r, loss(r), lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span>name)</span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="st">&quot;невязка $r = a(x) - y$&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="vs">r&quot;</span><span class="dv">$\\m</span><span class="vs">athcal{L}</span><span class="kw">(</span><span class="vs">r</span><span class="kw">)</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Три функции потерь&quot;</span>)<span class="op">;</span> ax.legend()</span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<h3 id="задание-11-эмпирический-риск">Задание 1.1. Эмпирический\nриск</h3>\n<p>Простейшая модель алгоритмов — константы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>≡</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">a(x)\\equiv c</annotation></semantics></math>.\nПринцип ERM (опр. 1.13) требует найти\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>c</mi><mo>*</mo></msup><mo>=</mo><mrow><mi>arg</mi><mo>⁡</mo></mrow><msub><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>c</mi></msub><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>c</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">c^* = \\arg\\min_c Q(c)</annotation></semantics></math>.\nНачнём с самой функции\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>.</p>\n</div>\n<div id="cell009" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> empirical_risk(loss, pred, y):</span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Q(a, X^l) -- среднее значение потерь по выборке.&quot;&quot;&quot;</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (1 строка): среднее значение loss(pred - y)</span></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a>y_sample <span class="op">=</span> rng.gamma(shape<span class="op">=</span><span class="fl">2.0</span>, scale<span class="op">=</span><span class="fl">3.0</span>, size<span class="op">=</span><span class="dv">400</span>)     <span class="co"># заведомо несимметричное</span></span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;Q константы 5.0 при квадратичной потере: &quot;</span></span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;</span><span class="sc">{</span>empirical_risk(loss_squared, <span class="fl">5.0</span>, y_sample)<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell010" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Минимизируем Q(c) по константе c для каждой потери</span></span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>grid <span class="op">=</span> np.linspace(y_sample.<span class="bu">min</span>(), y_sample.<span class="bu">max</span>(), <span class="dv">600</span>)</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a>optimum <span class="op">=</span> {}</span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> loss, name <span class="kw">in</span> [(loss_squared, <span class="st">&quot;квадратичная&quot;</span>), (loss_absolute, <span class="st">&quot;абсолютная&quot;</span>),</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a>                   (loss_quantile, <span class="st">&quot;квантильная, q=0.75&quot;</span>)]:</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>    risks <span class="op">=</span> np.array([empirical_risk(loss, c, y_sample) <span class="cf">for</span> c <span class="kw">in</span> grid])</span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>    optimum[name] <span class="op">=</span> grid[risks.argmin()]</span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> name, c <span class="kw">in</span> optimum.items():</span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>name<span class="sc">:22s}</span><span class="ss">: c* = </span><span class="sc">{</span>c<span class="sc">:6.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="ch">\\n</span><span class="ss">среднее выборки  = </span><span class="sc">{</span>y_sample<span class="sc">.</span>mean()<span class="sc">:6.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;медиана          = </span><span class="sc">{</span>np<span class="sc">.</span>median(y_sample)<span class="sc">:6.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;квантиль 0.75    = </span><span class="sc">{</span>np<span class="sc">.</span>quantile(y_sample, <span class="fl">0.75</span>)<span class="sc">:6.3f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какой выборочной характеристике равен\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>c</mi><mo>*</mo></msup><annotation encoding="application/x-tex">c^*</annotation></semantics></math>\nдля каждой потери? Продифференцируйте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>c</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(c)</annotation></semantics></math>\nпо\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>c</mi><annotation encoding="application/x-tex">c</annotation></semantics></math>\nдля квадратичной потери и убедитесь.</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell012" class="cell markdown">\n<hr />\n<h1 id="часть-2-проверяем-утверждение-112">Часть 2. Проверяем\nутверждение 1.12</h1>\n<p>Утверждение 1.12: если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>X</mi><mi>ℓ</mi></msup><annotation encoding="application/x-tex">X^\\ell</annotation></semantics></math>\n— простая выборка, то\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>𝔼</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">[</mo><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">]</mo><mo>=</mo><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathbb{E}\\bigl[Q(a, X^\\ell)\\bigr] = R(a)</annotation></semantics></math>.</p>\n<p>Ключевое слово — <strong>алгоритм\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>a</mi><annotation encoding="application/x-tex">a</annotation></semantics></math>\nфиксирован до того, как увидена выборка</strong>. В доказательстве\nиспользуется, что потери\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathcal L(a, x_i, y_i)</annotation></semantics></math>\nодинаково распределены; если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>a</mi><annotation encoding="application/x-tex">a</annotation></semantics></math>\nсам подобран по\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>X</mi><mi>ℓ</mi></msup><annotation encoding="application/x-tex">X^\\ell</annotation></semantics></math>,\nэто рассуждение рушится.</p>\n<p>Проверим оба случая на модели, где всё считается точно:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>∼</mo><mi>U</mi><mo stretchy="false" form="prefix">[</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">x\\sim U[0,1]</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>=</mo><msub><mi>θ</mi><mn>0</mn></msub><mo>+</mo><msub><mi>θ</mi><mn>1</mn></msub><mi>x</mi><mo>+</mo><mi>ε</mi></mrow><annotation encoding="application/x-tex">y = \\theta_0 + \\theta_1 x + \\varepsilon</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi><mo>∼</mo><mi>𝒩</mi><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><msup><mi>σ</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\varepsilon\\sim\\mathcal N(0,\\sigma^2)</annotation></semantics></math>.\nДля истинного алгоритма\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>a</mi><mo>*</mo></msup><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mi>θ</mi><mn>0</mn></msub><mo>+</mo><msub><mi>θ</mi><mn>1</mn></msub><mi>x</mi></mrow><annotation encoding="application/x-tex">a^*(x) = \\theta_0 + \\theta_1 x</annotation></semantics></math>\nистинный риск равен в точности\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>a</mi><mo>*</mo></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>𝔼</mi><msup><mi>ε</mi><mn>2</mn></msup><mo>=</mo><msup><mi>σ</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R(a^*) = \\mathbb{E}\\varepsilon^2 = \\sigma^2</annotation></semantics></math>.</p>\n</div>\n<div id="cell013" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>THETA_TRUE <span class="op">=</span> np.array([<span class="fl">2.0</span>, <span class="fl">3.0</span>])     <span class="co"># свободный член и наклон</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>SIGMA, ELL, N_REPEAT <span class="op">=</span> <span class="fl">0.8</span>, <span class="dv">30</span>, <span class="dv">3000</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> sample(n, generator):</span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Простая выборка (опр. 1.7) из распределения p(x, y).&quot;&quot;&quot;</span></span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>    x <span class="op">=</span> generator.uniform(<span class="dv">0</span>, <span class="dv">1</span>, n)</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a>    X <span class="op">=</span> np.column_stack([np.ones(n), x])</span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> X, X <span class="op">@</span> THETA_TRUE <span class="op">+</span> generator.normal(<span class="dv">0</span>, SIGMA, n)</span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-12"><a href="#cb7-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;истинный риск R(a*) = sigma^2 = </span><span class="sc">{</span>SIGMA <span class="op">**</span> <span class="dv">2</span><span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell014" class="cell markdown">\n<h3 id="задание-21-фиксированный-алгоритм">Задание 2.1. Фиксированный\nалгоритм</h3>\n<p>Повторим эксперимент\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>N</mi><annotation encoding="application/x-tex">N</annotation></semantics></math>\nраз: генерируем выборку и считаем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>a</mi><mo>*</mo></msup><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(a^*, X^\\ell)</annotation></semantics></math>\nдля <strong>истинного</strong> алгоритма — того самого, что был известен\nдо всех выборок.</p>\n</div>\n<div id="cell015" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>gen <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>Q_fixed <span class="op">=</span> np.empty(N_REPEAT)</span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> t <span class="kw">in</span> <span class="bu">range</span>(N_REPEAT):</span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a>    X, y <span class="op">=</span> sample(ELL, gen)</span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (1 строка): Q для ИСТИННОГО алгоритма, то есть предсказания X @ THETA_TRUE</span></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>    Q_fixed[t] <span class="op">=</span> ...</span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;R(a*)             = </span><span class="sc">{</span>SIGMA <span class="op">**</span> <span class="dv">2</span><span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;среднее Q         = </span><span class="sc">{</span>Q_fixed<span class="sc">.</span>mean()<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;смещение          = </span><span class="sc">{</span>Q_fixed<span class="sc">.</span>mean() <span class="op">-</span> SIGMA <span class="op">**</span> <span class="dv">2</span><span class="sc">:+.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell016" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Теперь алгоритм подбирается ПО ТОЙ ЖЕ выборке (принцип ERM)</span></span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a>gen <span class="op">=</span> np.random.default_rng(RANDOM_STATE <span class="op">+</span> <span class="dv">1</span>)</span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>X_big, y_big <span class="op">=</span> sample(<span class="dv">200_000</span>, gen)          <span class="co"># «генеральная совокупность» для оценки R</span></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>Q_train, R_hat <span class="op">=</span> np.empty(N_REPEAT), np.empty(N_REPEAT)</span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> t <span class="kw">in</span> <span class="bu">range</span>(N_REPEAT):</span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a>    X, y <span class="op">=</span> sample(ELL, gen)</span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a>    theta <span class="op">=</span> np.linalg.lstsq(X, y, rcond<span class="op">=</span><span class="va">None</span>)[<span class="dv">0</span>]</span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a>    Q_train[t] <span class="op">=</span> empirical_risk(loss_squared, X <span class="op">@</span> theta, y)</span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a>    R_hat[t] <span class="op">=</span> empirical_risk(loss_squared, X_big <span class="op">@</span> theta, y_big)</span></code></pre></div>\n</div>\n<div id="cell017" class="cell code">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a>p <span class="op">=</span> <span class="dv">2</span>                                        <span class="co"># число параметров модели</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;sigma^2                    = </span><span class="sc">{</span>SIGMA <span class="op">**</span> <span class="dv">2</span><span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;среднее Q(a_hat, X^l)      = </span><span class="sc">{</span>Q_train<span class="sc">.</span>mean()<span class="sc">:.4f}</span><span class="ss">&quot;</span></span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;   теория sigma^2(1 - p/l) = </span><span class="sc">{</span>SIGMA <span class="op">**</span> <span class="dv">2</span> <span class="op">*</span> (<span class="dv">1</span> <span class="op">-</span> p <span class="op">/</span> ELL)<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;среднее R(a_hat)           = </span><span class="sc">{</span>R_hat<span class="sc">.</span>mean()<span class="sc">:.4f}</span><span class="ss">&quot;</span></span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;   теория sigma^2(1 + p/l) = </span><span class="sc">{</span>SIGMA <span class="op">**</span> <span class="dv">2</span> <span class="op">*</span> (<span class="dv">1</span> <span class="op">+</span> p <span class="op">/</span> ELL)<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;зазор R - Q                = </span><span class="sc">{</span>(R_hat <span class="op">-</span> Q_train)<span class="sc">.</span>mean()<span class="sc">:.4f}</span><span class="ss">&quot;</span></span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;   теория 2 sigma^2 p/l    = </span><span class="sc">{</span><span class="dv">2</span> <span class="op">*</span> SIGMA <span class="op">**</span> <span class="dv">2</span> <span class="op">*</span> p <span class="op">/</span> ELL<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell018" class="cell code">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a>bins <span class="op">=</span> np.linspace(<span class="dv">0</span>, np.percentile(R_hat, <span class="fl">99.5</span>), <span class="dv">60</span>)</span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a>ax.hist(Q_train, bins<span class="op">=</span>bins, alpha<span class="op">=</span><span class="fl">0.65</span>, density<span class="op">=</span><span class="va">True</span>, label<span class="op">=</span><span class="vs">r&quot;</span><span class="dv">$</span><span class="vs">Q</span><span class="dv">$</span><span class="vs"> на обучающей&quot;</span>)</span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a>ax.hist(R_hat, bins<span class="op">=</span>bins, alpha<span class="op">=</span><span class="fl">0.65</span>, density<span class="op">=</span><span class="va">True</span>, label<span class="op">=</span><span class="vs">r&quot;</span><span class="dv">$</span><span class="vs">R</span><span class="dv">$</span><span class="vs"> истинный&quot;</span>)</span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a>ax.axvline(SIGMA <span class="op">**</span> <span class="dv">2</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="vs">r&quot;</span><span class="dv">$\\s</span><span class="vs">igma</span><span class="dv">^</span><span class="vs">2</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="st">&quot;риск&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="st">&quot;плотность&quot;</span>)<span class="op">;</span> ax.legend()</span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Алгоритм выбран по выборке: обучающая ошибка смещена вниз&quot;</span>)</span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell019" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Для фиксированного алгоритма смещения нет,\nдля обученного — есть. В каком месте доказательства утверждения 1.12\nломается рассуждение? Как зазор зависит от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\nи числа параметров\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>p</mi><annotation encoding="application/x-tex">p</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell020" class="cell markdown">\n<hr />\n<h1 id="часть-3-мнк-воспроизводим-пример-из-конспекта">Часть 3. МНК:\nвоспроизводим пример из конспекта</h1>\n<p>Теорема 1.20: если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nневырождена, то\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">\\theta^* = (X^{\\mathsf T}X)^{-1}X^{\\mathsf T}y</annotation></semantics></math>.</p>\n<p>Формулу с обратной матрицей <strong>не реализуют буквально</strong> —\nрешают систему. В примере 1.21 конспекта МНК применён к выборке из\nвосьми кошек\n(<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>f</mi><mn>1</mn></msub><annotation encoding="application/x-tex">f_1</annotation></semantics></math>\n— банок корма в день,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>f</mi><mn>2</mn></msub><annotation encoding="application/x-tex">f_2</annotation></semantics></math>\n— возраст,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>\n— вес) и получено\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>≈</mo><mo stretchy="false" form="prefix">(</mo><mn>2.201</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.893</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.114</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\theta^*\\approx(2.201,\\ 0.893,\\ 0.114)</annotation></semantics></math>.\nПроверим.</p>\n</div>\n<div id="cell021" class="cell markdown">\n<blockquote>\n<p><strong>Напоминание — число обусловленности.</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(A)</annotation></semantics></math>\n— отношение наибольшего сингулярного числа\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>A</mi><annotation encoding="application/x-tex">A</annotation></semantics></math>\nк наименьшему. Практический смысл: если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mn>10</mn><mi>k</mi></msup></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(A)=10^{k}</annotation></semantics></math>,\nпри решении системы с матрицей\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>A</mi><annotation encoding="application/x-tex">A</annotation></semantics></math>\nтеряется около\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nверных десятичных знаков, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo>=</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\mathrm{cond}=\\infty</annotation></semantics></math>\nозначает вырожденность. Ключевой факт этой части:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(X^{\\mathsf T}X) = \\mathrm{cond}(X)^2</annotation></semantics></math>\n— переходя к нормальным уравнениям, мы <strong>удваиваем</strong> потерю\nточности. В NumPy: <code>np.linalg.cond(A)</code>.</p>\n</blockquote>\n</div>\n<div id="cell022" class="cell code">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a>f1 <span class="op">=</span> np.array([<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">1</span>, <span class="dv">4</span>], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a>f2 <span class="op">=</span> np.array([<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">5</span>, <span class="dv">7</span>, <span class="dv">10</span>, <span class="dv">2</span>, <span class="dv">8</span>], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a>y_cats <span class="op">=</span> np.array([<span class="fl">3.0</span>, <span class="fl">4.2</span>, <span class="fl">4.5</span>, <span class="fl">5.5</span>, <span class="fl">4.8</span>, <span class="fl">6.0</span>, <span class="fl">3.4</span>, <span class="fl">6.6</span>])</span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a>X_cats <span class="op">=</span> np.column_stack([np.ones(<span class="dv">8</span>), f1, f2])      <span class="co"># столбец единиц под theta_0</span></span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a>theta_solve <span class="op">=</span> np.linalg.solve(X_cats.T <span class="op">@</span> X_cats, X_cats.T <span class="op">@</span> y_cats)</span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a>theta_lstsq <span class="op">=</span> np.linalg.lstsq(X_cats, y_cats, rcond<span class="op">=</span><span class="va">None</span>)[<span class="dv">0</span>]</span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;нормальные уравнения (solve): </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">round</span>(theta_solve, <span class="dv">4</span>)<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;SVD-решение (lstsq)         : </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">round</span>(theta_lstsq, <span class="dv">4</span>)<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;в конспекте                 : [2.201  0.893  0.114]&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell023" class="cell code">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Почему не считают (X^T X)^{-1} явно: переход к нормальным уравнениям</span></span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a><span class="co"># возводит число обусловленности в квадрат.</span></span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;cond(X)      = </span><span class="sc">{</span>np<span class="sc">.</span>linalg<span class="sc">.</span>cond(X_cats)<span class="sc">:10.1f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;cond(X^T X)  = </span><span class="sc">{</span>np<span class="sc">.</span>linalg<span class="sc">.</span>cond(X_cats.T <span class="op">@</span> X_cats)<span class="sc">:10.1f}</span><span class="ss">&quot;</span></span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;   = cond(X)^2 = </span><span class="sc">{</span>np<span class="sc">.</span>linalg<span class="sc">.</span>cond(X_cats) <span class="op">**</span> <span class="dv">2</span><span class="sc">:.1f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="ch">\\n</span><span class="ss">Q(theta*) = </span><span class="sc">{</span>empirical_risk(loss_squared, X_cats <span class="op">@</span> theta_solve, y_cats)<span class="sc">:.6f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell024" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпало ли с конспектом? Что означает\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(X^{\\mathsf T}X) = \\mathrm{cond}(X)^2</annotation></semantics></math>\nдля точности вычислений?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell025" class="cell markdown">\n<hr />\n<h1 id="часть-4-полиномы-первое-переобучение">Часть 4. Полиномы: первое\nпереобучение</h1>\n<p>Как отмечено в примере 1.4 конспекта, признаками линейной модели\nмогут служить любые функции исходных данных: при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mi>x</mi><mrow><mspace width="0.167em"></mspace><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msup></mrow><annotation encoding="application/x-tex">f_j(x) = x^{\\,j-1}</annotation></semantics></math>\nта же формула задаёт полином. Модель остаётся <strong>линейной по\nпараметрам</strong>, весь аппарат МНК применим.</p>\n<p>Посмотрим, что происходит с ростом степени.</p>\n</div>\n<div id="cell026" class="cell code">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> make_pipeline</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> PolynomialFeatures</span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a>true_f <span class="op">=</span> <span class="kw">lambda</span> t: np.sin(<span class="dv">3</span> <span class="op">*</span> t) <span class="op">+</span> <span class="fl">0.5</span> <span class="op">*</span> t</span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a>x_tr <span class="op">=</span> np.sort(rng.uniform(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>, <span class="dv">30</span>))</span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a>x_te <span class="op">=</span> np.sort(rng.uniform(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>, <span class="dv">500</span>))</span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a>y_tr <span class="op">=</span> true_f(x_tr) <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.25</span>, <span class="dv">30</span>)</span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a>y_te <span class="op">=</span> true_f(x_te) <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.25</span>, <span class="dv">500</span>)</span>\n<span id="cb14-9"><a href="#cb14-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-10"><a href="#cb14-10" aria-hidden="true" tabindex="-1"></a>fit_poly <span class="op">=</span> <span class="kw">lambda</span> d: make_pipeline(PolynomialFeatures(d), LinearRegression()).fit(</span>\n<span id="cb14-11"><a href="#cb14-11" aria-hidden="true" tabindex="-1"></a>    x_tr[:, <span class="va">None</span>], y_tr)</span></code></pre></div>\n</div>\n<div id="cell027" class="cell markdown">\n<h3 id="задание-41-ошибка-на-обучении-и-на-контроле">Задание 4.1. Ошибка\nна обучении и на контроле</h3>\n<p>Для каждой степени посчитайте эмпирический риск на обучающей выборке\nи на контрольной. Обратите внимание: контрольная выборка в обучении не\nучаствовала.</p>\n</div>\n<div id="cell028" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>degrees <span class="op">=</span> [<span class="dv">1</span>, <span class="dv">3</span>, <span class="dv">5</span>, <span class="dv">7</span>, <span class="dv">9</span>, <span class="dv">12</span>, <span class="dv">15</span>]</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> d <span class="kw">in</span> degrees:</span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a>    model <span class="op">=</span> fit_poly(d)</span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (2 строки): Q на обучающей (x_tr, y_tr) и на контрольной (x_te, y_te)</span></span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;степень&quot;</span>: d, <span class="st">&quot;Q обучающая&quot;</span>: ..., <span class="st">&quot;Q контрольная&quot;</span>: ...})</span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a>table <span class="op">=</span> pd.DataFrame(rows).set_index(<span class="st">&quot;степень&quot;</span>)</span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a>display(table.<span class="bu">round</span>(<span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell029" class="cell code">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a>fig, (ax1, ax2) <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">2</span>, figsize<span class="op">=</span>(<span class="dv">12</span>, <span class="dv">4</span>))</span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a>grid <span class="op">=</span> np.linspace(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>, <span class="dv">400</span>)</span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a>ax1.scatter(x_tr, y_tr, s<span class="op">=</span><span class="dv">25</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, zorder<span class="op">=</span><span class="dv">3</span>, label<span class="op">=</span><span class="st">&quot;обучающая выборка&quot;</span>)</span>\n<span id="cb16-4"><a href="#cb16-4" aria-hidden="true" tabindex="-1"></a>ax1.plot(grid, true_f(grid), <span class="st">&quot;k--&quot;</span>, lw<span class="op">=</span><span class="fl">1.5</span>, label<span class="op">=</span><span class="st">&quot;истинная зависимость&quot;</span>)</span>\n<span id="cb16-5"><a href="#cb16-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> d <span class="kw">in</span> (<span class="dv">1</span>, <span class="dv">5</span>, <span class="dv">15</span>):</span>\n<span id="cb16-6"><a href="#cb16-6" aria-hidden="true" tabindex="-1"></a>    ax1.plot(grid, fit_poly(d).predict(grid[:, <span class="va">None</span>]), lw<span class="op">=</span><span class="fl">1.8</span>, label<span class="op">=</span><span class="ss">f&quot;степень </span><span class="sc">{</span>d<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb16-7"><a href="#cb16-7" aria-hidden="true" tabindex="-1"></a>ax1.set_ylim(y_tr.<span class="bu">min</span>() <span class="op">-</span> <span class="dv">1</span>, y_tr.<span class="bu">max</span>() <span class="op">+</span> <span class="dv">1</span>)<span class="op">;</span> ax1.legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb16-8"><a href="#cb16-8" aria-hidden="true" tabindex="-1"></a>ax1.set_xlabel(<span class="st">&quot;$x$&quot;</span>)<span class="op">;</span> ax1.set_ylabel(<span class="st">&quot;$y$&quot;</span>)<span class="op">;</span> ax1.set_title(<span class="st">&quot;Полиномы разных степеней&quot;</span>)</span>\n<span id="cb16-9"><a href="#cb16-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-10"><a href="#cb16-10" aria-hidden="true" tabindex="-1"></a>ax2.plot(table.index, table[<span class="st">&quot;Q обучающая&quot;</span>], <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;обучающая&quot;</span>)</span>\n<span id="cb16-11"><a href="#cb16-11" aria-hidden="true" tabindex="-1"></a>ax2.plot(table.index, table[<span class="st">&quot;Q контрольная&quot;</span>], <span class="st">&quot;s-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;контрольная&quot;</span>)</span>\n<span id="cb16-12"><a href="#cb16-12" aria-hidden="true" tabindex="-1"></a>ax2.set_yscale(<span class="st">&quot;log&quot;</span>)<span class="op">;</span> ax2.set_xlabel(<span class="st">&quot;степень&quot;</span>)<span class="op">;</span> ax2.set_ylabel(<span class="st">&quot;$Q$&quot;</span>)</span>\n<span id="cb16-13"><a href="#cb16-13" aria-hidden="true" tabindex="-1"></a>ax2.set_title(<span class="st">&quot;Риск против сложности модели&quot;</span>)<span class="op">;</span> ax2.legend()</span>\n<span id="cb16-14"><a href="#cb16-14" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell030" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Как ведут себя обе ошибки с ростом степени?\nКакая степень оптимальна и можно ли было выбрать её по обучающей\nошибке?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell031" class="cell markdown">\n<hr />\n<h1 id="часть-5-своя-выборка">Часть 5. Своя выборка</h1>\n<p>Применим МНК к индивидуальным данным. Функция\n<code>load_personal</code> повторяет предобработку занятия 1, чтобы\nрезультат не зависел от аккуратности вашего кода.</p>\n</div>\n<div id="cell032" class="cell code">\n<div class="sourceCode" id="cb17"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb17-1"><a href="#cb17-1" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb17-2"><a href="#cb17-2" aria-hidden="true" tabindex="-1"></a>Xtr, Xte <span class="op">=</span> data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>]</span>\n<span id="cb17-3"><a href="#cb17-3" aria-hidden="true" tabindex="-1"></a>ytr, yte <span class="op">=</span> data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]</span>\n<span id="cb17-4"><a href="#cb17-4" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>data[<span class="st">&#39;domain&#39;</span>]<span class="sc">}</span><span class="ss">: </span><span class="sc">{</span>data[<span class="st">&#39;task&#39;</span>]<span class="sc">}</span><span class="ss">, обучающая </span><span class="sc">{</span>Xtr<span class="sc">.</span>shape<span class="sc">}</span><span class="ss">, контрольная </span><span class="sc">{</span>Xte<span class="sc">.</span>shape<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb17-5"><a href="#cb17-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb17-6"><a href="#cb17-6" aria-hidden="true" tabindex="-1"></a>model <span class="op">=</span> LinearRegression().fit(Xtr, ytr)</span>\n<span id="cb17-7"><a href="#cb17-7" aria-hidden="true" tabindex="-1"></a>const <span class="op">=</span> ytr.mean()</span>\n<span id="cb17-8"><a href="#cb17-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb17-9"><a href="#cb17-9" aria-hidden="true" tabindex="-1"></a>q_const <span class="op">=</span> empirical_risk(loss_squared, const, yte)</span>\n<span id="cb17-10"><a href="#cb17-10" aria-hidden="true" tabindex="-1"></a>q_model <span class="op">=</span> empirical_risk(loss_squared, model.predict(Xte), yte)</span>\n<span id="cb17-11"><a href="#cb17-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="ch">\\n</span><span class="ss">Q на контроле: константа </span><span class="sc">{</span>q_const<span class="sc">:.4g}</span><span class="ss"> | МНК </span><span class="sc">{</span>q_model<span class="sc">:.4g}</span><span class="ss">&quot;</span>)</span>\n<span id="cb17-12"><a href="#cb17-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;R^2 = 1 - Q_МНК / Q_конст = </span><span class="sc">{</span><span class="dv">1</span> <span class="op">-</span> q_model <span class="op">/</span> q_const<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell033" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Насколько МНК лучше константного прогноза?\nЧто означает\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">R^2 = 0</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell034" class="cell markdown">\n<h2 id="итоги-занятия">Итоги занятия</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Утверждение 1.12 говорит, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>𝔼</mi><mo stretchy="false" form="prefix">[</mo><mi>Q</mi><mo stretchy="false" form="postfix">]</mo><mo>=</mo><mi>R</mi></mrow><annotation encoding="application/x-tex">\\mathbb{E}[Q] = R</annotation></semantics></math>.\nПочему это не противоречит переобучению? Сформулируйте условие, при\nкотором равенство верно.</li>\n<li>Вы получили\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mover><mi>a</mi><mo accent="true">̂</mo></mover><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">Q(\\hat a, X^\\ell) = 0</annotation></semantics></math>.\nЧто это говорит о качестве на новых объектах? Приведите алгоритм с\nнулевым эмпирическим риском и максимально плохим истинным.</li>\n<li>Почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">\\theta^* = (X^{\\mathsf T}X)^{-1}X^{\\mathsf T}y</annotation></semantics></math>\n— правильная формула, но неправильная реализация?</li>\n<li>Модель полиномов степени\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≤</mo><mi>d</mi></mrow><annotation encoding="application/x-tex">\\le d</annotation></semantics></math>\nвложена в модель степени\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≤</mo><mi>d</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\le d+1</annotation></semantics></math>.\nДокажите, что минимум эмпирического риска по большей модели не больше.\nПочему из этого <strong>не</strong> следует, что большая модель\nлучше?</li>\n</ol>\n<hr />\n<p><strong>Дома:</strong> откройте <code>lab02_homework.ipynb</code> —\nтам три задачи: матричное дифференцирование, пять способов решить МНК и\nсвязь функции потерь с распределением шума.</p>\n</div>\n</body>\n</html>\n'}}]);